SELECT 'core-2026-09-v4','present-simple-be','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"present-simple-be","title":"Present simple: be","level":"A1","order":4,"summary":"Match am, is and are to the subject, then build statements, negatives and questions.","learningGoals":["Present forms","Negatives and questions","Contractions"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Present forms","explanation":"Use am with I, is with a singular subject, and are with you or a plural subject. Be describes identity, location or a state.","examples":["I am near the exit.","The keys are on a hook."]},{"title":"Negatives and questions","explanation":"Place not after be. For a standard yes/no question, put be before the subject. Do not add do or does.","examples":["The door is not locked.","Are the seats free?"]},{"title":"Contractions","explanation":"In everyday English, I am becomes I’m and they are becomes they’re. Full forms remain correct. In positive short answers, keep the full verb.","examples":["Yes, we are.","No, it is not."]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-be","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Be links a subject to an identity, a state or a location. It does not need another action verb to make a complete sentence: The room is quiet is already complete. First identify the subject, then select the form of be. English normally keeps this verb where some other languages would leave it out."],"rules":[{"title":"Present forms","explanation":"Use am with I, is with a singular subject, and are with you or a plural subject. Be describes identity, location or a state.","examples":["I am near the exit.","The keys are on a hook.","The books **are** heavy, but the bag **is** light."],"pattern":"**I am** · **he / she / it is** · **you / we / they are**","paragraphs":["A noun phrase can be longer than one word. In The keys on the table are mine, keys is the head and is plural. A phrase beginning with you takes are even when you are addressing only one person. A name such as Mia normally takes is."],"id":"present-simple-be-foundation-1","domain":"verbs","referenceIds":["bc-be","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Negatives and questions","explanation":"Place not after be. For a standard yes/no question, put be before the subject. Do not add do or does.","examples":["The door is not locked.","Are the seats free?","Where **are** my glasses? — They **are** on the desk."],"pattern":"Subject + **be + not** / **Be + subject**?","paragraphs":["Be makes its own negative and question. The statement She is ready becomes She is not ready and Is she ready? Do not borrow do from the present-simple action-verb pattern. A question word goes before the inverted verb: Where are the keys?"],"id":"present-simple-be-foundation-2","domain":"verbs","referenceIds":["bc-be","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contractions","explanation":"In everyday English, I am becomes I’m and they are becomes they’re. Full forms remain correct. In positive short answers, keep the full verb.","examples":["Yes, we are.","No, it is not.","It **is not** cold. / It **isn’t** cold."],"pattern":"Yes, I **am**. / No, I **am not**.","paragraphs":["Contractions make speech and informal writing shorter: I’m, you’re, she’s, isn’t and aren’t. Full forms are still correct and may add emphasis. A positive short answer normally ends with a full auxiliary: Yes, she is, not Yes, she’s."],"id":"present-simple-be-foundation-3","domain":"verbs","referenceIds":["bc-be","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Be also appears as an auxiliary in continuous and passive constructions. Compare She is happy (a state), She is reading (an activity in progress), and The letter is signed (a passive or a resulting state). The words after be determine its role.","examples":["The books **are** heavy, but the bag **is** light.","Where **are** my glasses? — They **are** on the desk.","It **is not** cold. / It **isn’t** cold."],"id":"present-simple-be-foundation-4","domain":"verbs","referenceIds":["bc-be","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"verbs","id":"auxiliary-and-lexical-verbs","title":"Main verbs, auxiliaries and the first auxiliary","explanation":"Be, have and do can act as main verbs or auxiliaries. Auxiliaries build questions, negatives, aspect, voice and emphasis. In a chain, the first auxiliary carries tense and agreement and moves in a question. Later verbs take the form required by the preceding auxiliary. A lexical verb may need do-support when no other auxiliary is available.","pattern":"**Has** she **been working**?","examples":["They **have** a car. / They **have finished**.","He **does** the shopping. / **Does** he shop here?"],"commonMistakes":["Possessive have uses different question patterns across varieties: Do you have…? is widely used; Have you got…? is especially common in British conversation."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"inflection","id":"contraction-ambiguity","title":"Contractions, strong forms and ambiguity","explanation":"A contraction reduces an auxiliary or negative in writing to reflect common spoken forms. ’s can mean is or has; ’d can mean had or would. Read the following verb to resolve the form. Positive contracted auxiliaries normally cannot stand alone at the end of a short answer where stress falls on them.","pattern":"She**’s** waiting / She**’s** finished","examples":["Yes, **I am**, not Yes, I’m.","I **would have** helped. / I**’d have** helped."],"commonMistakes":["Could’ve is a contraction of could have, not could of. The sound resemblance does not change the auxiliary construction."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**I am** · **he / she / it is** · **you / we / they are**","Subject + **be + not** / **Be + subject**?","Yes, I **am**. / No, I **am not**."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["pronouns-and-possessive-determiners"],"readingReferenceIds":["bc-be","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='present-simple-be'
